const hourlyRecordCounts = [
  2, 2, 1, 1, 1, 1, 2, 3, 3, 4, 5, 6, 7, 6, 5, 7, 8, 9, 10, 9, 8, 7, 7, 6,
];

// Assign stable IDs and actual observation timestamps; each record has its own original and exact quotation.
export const sampleArticles: Article[] = topicSeeds.flatMap(
  (topic, topicIndex) =>
    topic.records.map(([sentiment, source, title, content], index) => {
      const ordinal =
        topicSeeds
          .slice(0, topicIndex)
          .reduce((n, t) => n + t.records.length, 0) +
        index +
        1;
      const suffix = String(ordinal).padStart(3, "0");
      // Interleave topics into the 120 timestamp slots; charts then count originals rather than inventing a line.
      let slot = ((ordinal - 1) * 37 + 119) % 120;
      let hour = 0;
      while (slot >= hourlyRecordCounts[hour])
        slot -= hourlyRecordCounts[hour++];
      const minute = Math.floor(((slot + 0.5) * 60) / hourlyRecordCounts[hour]);
      const date = new Date(Date.UTC(2026, 10, 2, 14 + hour, 30 + minute));
      const local = date.toISOString().slice(0, 16);
      return {
        id: `DOC-1103-${suffix}`,
        evidence: `EVD-20261103-${suffix}`,
        topicId: topic.id,
        topic: topic.title,
        category: topic.category,
        title,
        content,
        sentiment,
        source,
        time: local.slice(11),
        observedAt: `${local}:00+08:00`,
        author:
          source === "公开社区"
            ? `市民 QL${suffix}`
            : source === "监管公告"
              ? "青岚市场监管信息台"
              : source === "政府 RSS"
                ? "青岚政务发布"
                : `${topic.category}资料整理组`,
        location: ["滨河片区", "东城片区", "滨江商圈", "锦澜社区", "滨湾片区"][
          topicIndex % 5
        ],
        quote: `${content.split("。")[0]}。`,
        verification:
          source === "公开社区"
            ? "公众表达 · 待交叉核验"
            : source === "资料导入"
              ? "整理材料 · 待原件核对"
              : "公开信息样本 · 按所述范围引用",
      };
    }),
);
